import{_ as a,H as t,f as s,i as o}from"./chunks/framework.CBmkDW73.js";const h=JSON.parse('{"title":"subagents","description":"","frontmatter":{},"headers":[],"relativePath":"skills/subagents.md","filePath":"en/skills/subagents.md"}'),n={name:"skills/subagents.md"};function i(l,e,r,d,c,p){return t(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="subagents" tabindex="-1">subagents <a class="header-anchor" href="#subagents" aria-label="Permalink to &quot;subagents&quot;">​</a></h1><p>The <code>subagents</code> skill dispatches independent <code>[parallel]</code> plan milestones to subagents with fresh context windows, explicit role charters, and optional capability-tiered model routing.</p><h2 id="dispatch-write-isolation" tabindex="-1">Dispatch &amp; Write Isolation <a class="header-anchor" href="#dispatch-write-isolation" aria-label="Permalink to &quot;Dispatch &amp; Write Isolation&quot;">​</a></h2><p>Expand milestone tasks into atomic steps only at dispatch time — pass spec/plan file paths rather than pasting inline content:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TASK: &lt;one sentence&gt;</span></span>
<span class="line"><span>ROLE: &lt;implementer | spec-reviewer | quality-reviewer&gt;</span></span>
<span class="line"><span>MODEL: &lt;fast | balanced | strongest&gt;</span></span>
<span class="line"><span>REPOSITORY / MODULE / FILES / SPEC / ACCEPTANCE / EXTRA</span></span></code></pre></div><p>One task owns one repository/module write scope; never dispatch concurrent writers to overlapping module roots. Coordinator dispatches integration tasks only after required modules report green local acceptance, and only the coordinator marks <code>- [x]</code>.</p><h2 id="role-loop-status-handling" tabindex="-1">Role Loop &amp; Status Handling <a class="header-anchor" href="#role-loop-status-handling" aria-label="Permalink to &quot;Role Loop &amp; Status Handling&quot;">​</a></h2><p>Execution loop per task: <code>implementer</code> (<code>balanced</code> default) → <code>spec-reviewer</code> (<code>fast</code> default) → <code>quality-reviewer</code> (<code>strongest</code> default) → coordinator marks complete. Handle subagent statuses explicitly:</p><ul><li><code>DONE_WITH_CONCERNS</code>: address correctness issues; note observations.</li><li><code>NEEDS_CONTEXT</code>: supply missing facts and re-dispatch.</li><li><code>BLOCKED</code>: diagnose root blocker rather than blind retry.</li></ul><h2 id="model-tiers" tabindex="-1">Model Tiers <a class="header-anchor" href="#model-tiers" aria-label="Permalink to &quot;Model Tiers&quot;">​</a></h2><p><code>MODEL</code> (<code>fast | balanced | strongest</code>) defaults to the harness model unless configured via <code>.praxis/model-tiers.yaml</code> (resolution order: project <code>.praxis/model-tiers.yaml</code> → user <code>~/.praxis/model-tiers.yaml</code> → harness default; template <code>model-tiers.example.yaml</code> under <code>tiers.&lt;tier&gt;.{provider, model}</code>).</p>`,11)])])}const m=a(n,[["render",i]]);export{h as __pageData,m as default};
